-- Additional test questions over Australian federal court judgments (legal), v3: any column, most need columns the initial build does not read.
-- QX1: For judges with at least fifteen cases: how many cases, how many were first judgments, and how many had evidence, busiest first?
SELECT judge_name, COUNT(*) AS cases, SUM(CASE WHEN first_judge = 1 THEN 1 ELSE 0 END) AS first_judgments, SUM(evidence) AS with_evidence FROM legal WHERE judge_name IS NOT NULL AND judge_name <> '' GROUP BY judge_name HAVING COUNT(*) >= 15 ORDER BY cases DESC, judge_name;
-- QX2: Per case type, for cases where counsel for the applicant is named versus not named: how many cases, and what share were dismissed?
SELECT case_type, CASE WHEN counsel_for_applicant IS NULL OR counsel_for_applicant = '' OR counsel_for_applicant LIKE '%in person%' THEN 'no counsel named' ELSE 'counsel named' END AS applicant_counsel, COUNT(*) AS cases, AVG(CASE WHEN verdict = 'Dismissed' THEN 1.0 ELSE 0.0 END) AS dismissal_rate FROM legal GROUP BY case_type, applicant_counsel;
-- QX3: Do applicants with senior counsel (SC or QC) win more often than applicants with other named counsel?
SELECT CASE WHEN counsel_for_applicant LIKE '% SC%' OR counsel_for_applicant LIKE '% QC%' THEN 'senior counsel' ELSE 'other counsel' END AS applicant_counsel, COUNT(*) AS cases, SUM(CASE WHEN verdict = 'Approved' THEN 1 ELSE 0 END) AS approved, AVG(CASE WHEN verdict = 'Approved' THEN 1.0 ELSE 0.0 END) AS approval_rate FROM legal WHERE counsel_for_applicant IS NOT NULL AND counsel_for_applicant <> '' AND counsel_for_applicant NOT LIKE '%in person%' GROUP BY applicant_counsel;
-- QX4: When a company, an organization or a government is the plaintiff, what kinds of defendant (company, organization, government) do they sue, and how many cases each?
SELECT plaintiff_current_status, defendant_current_status, COUNT(*) AS cases FROM legal WHERE plaintiff_current_status IN ('Company', 'Organization', 'Government') AND defendant_current_status IN ('Company', 'Organization', 'Government') GROUP BY plaintiff_current_status, defendant_current_status;
-- QX5: Per judgment year: in how many cases was a fine imposed, and what were the total and the largest fine?
SELECT judgment_year, COUNT(*) AS fined_cases, SUM(CAST(fine_amount AS REAL)) AS total_fines, MAX(CAST(fine_amount AS REAL)) AS largest_fine FROM legal WHERE CAST(fine_amount AS REAL) > 0 AND judgment_year IS NOT NULL AND judgment_year <> '' GROUP BY judgment_year;
-- QX6: By area of law of the charges (migration, tax, intellectual property, misleading conduct, insolvency, other): how many cases, and how many statutes and precedents are cited on average?
SELECT CASE WHEN charges LIKE '%refugee%' OR charges LIKE '%visa%' OR charges LIKE '%migration%' THEN 'migration' WHEN charges LIKE '%tax%' THEN 'tax' WHEN charges LIKE '%patent%' OR charges LIKE '%copyright%' OR charges LIKE '%trade mark%' OR charges LIKE '%trademark%' THEN 'intellectual property' WHEN charges LIKE '%misleading%' OR charges LIKE '%deceptive%' THEN 'misleading conduct' WHEN charges LIKE '%bankrupt%' OR charges LIKE '%insolven%' THEN 'insolvency' ELSE 'other' END AS area, COUNT(*) AS cases, AVG(legal_basis_num) AS average_statutes, AVG(case_number) AS average_precedents FROM legal WHERE charges IS NOT NULL AND charges <> '' GROUP BY area;
-- QX7: For government, company and organization defendants: how many cases, how many statutes and precedents are cited on average, and what share had evidence?
SELECT defendant_current_status, COUNT(*) AS cases, AVG(legal_basis_num) AS average_statutes, AVG(case_number) AS average_precedents, AVG(CASE WHEN evidence = 1 THEN 1.0 ELSE 0.0 END) AS evidence_rate FROM legal WHERE defendant_current_status IN ('Government', 'Company', 'Organization') GROUP BY defendant_current_status;
-- QX8: Which five judges heard the most cases against an immigration minister, and how many of those did they dismiss?
SELECT judge_name, COUNT(*) AS cases, SUM(CASE WHEN verdict = 'Dismissed' THEN 1 ELSE 0 END) AS dismissed FROM legal WHERE defendant LIKE '%Immigration%' AND judge_name IS NOT NULL AND judge_name <> '' GROUP BY judge_name ORDER BY cases DESC, judge_name LIMIT 5;
-- QX9: Per judgment year: how many judgments were delivered in the year the hearing began, and how many in a later year?
SELECT judgment_year, SUM(CASE WHEN CAST(judgment_year AS INTEGER) = CAST(hearing_year AS INTEGER) THEN 1 ELSE 0 END) AS same_year, SUM(CASE WHEN CAST(judgment_year AS INTEGER) > CAST(hearing_year AS INTEGER) THEN 1 ELSE 0 END) AS later_year FROM legal WHERE judgment_year IS NOT NULL AND judgment_year <> '' AND hearing_year IS NOT NULL AND hearing_year <> '' GROUP BY judgment_year;
-- QX10: Which judges with at least ten cases cite more precedents on average than the average case?
SELECT judge_name, COUNT(*) AS cases, AVG(case_number) AS average_precedents FROM legal WHERE judge_name IS NOT NULL AND judge_name <> '' GROUP BY judge_name HAVING COUNT(*) >= 10 AND AVG(case_number) > (SELECT AVG(case_number) FROM legal) ORDER BY average_precedents DESC, judge_name;
